<?php require_once 'db.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check();$name=trim($_POST['name']??'Administrator');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){$err='Use a valid email and password of at least 8 characters.';}else{$s=db()->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);echo 'Admin created. Delete setup_admin.php now, then <a href="login.php">sign in</a>.';exit;}} include 'header.php'; ?>
